function statusLabel(value){const labels={ACTIVE:"Ativo",WAITING_CUSTOMER:"Aguardando cliente",WAITING_HUMAN:"Aguardando humano",CLOSED:"Encerrado",WAITING_BUSINESS:"Aguardando oficina",REQUESTED:"Solicitado",WAITING_INFORMATION:"Aguardando informações",RESPONDED:"Respondido",CANCELLED:"Cancelado",OPEN:"Aberta",CONVERTED:"Convertida",LOST:"Perdida",DELIVERED:"Entregue",PENDING:"Pendente",SENDING:"Enviando",FAILED_RETRYABLE:"Falha temporária",FAILED_FINAL:"Falha definitiva",WEB:"Web",WHATSAPP:"WhatsApp",VOICE:"Voz",INTERNAL:"Interno",CUSTOMER:"Cliente",ASSISTANT:"Miguel",HUMAN_AGENT:"Humano",SYSTEM:"Sistema",GENERAL_INFORMATION:"Informação geral",SERVICE_INQUIRY:"Consulta de serviço",QUOTE_REQUEST:"Orçamento",APPOINTMENT_REQUEST:"Agendamento",APPOINTMENT_CHANGE:"Alteração de agendamento",APPOINTMENT_CANCEL:"Cancelamento de agendamento",VEHICLE_STATUS:"Status do veículo",WARRANTY:"Garantia",COMPLAINT:"Reclamação",HUMAN_REQUEST:"Solicitação humana",SYMPTOM_REPORT:"Relato de sintoma",OTHER:"Outro",UNKNOWN:"Não identificado",QUOTE_REQUESTED:"Orçamento solicitado",QUOTE_RESPONDED:"Orçamento respondido",QUOTE_PUBLISHED:"Orçamento publicado",CNPJ_VALIDATED:"CNPJ validado",PUBLIC_LISTING_ONLY:"Listagem pública — CNPJ ainda não validado",CNPJ_NOT_FOUND:"CNPJ não localizado",CNPJ_AMBIGUOUS:"Validação cadastral inconclusiva"};return labels[value]||value||"—";}
