function statusClass(value){if(["DELIVERED","RESPONDED","CONVERTED","CNPJ_VALIDATED"].includes(value))return "success";if(["FAILED_RETRYABLE","FAILED_FINAL"].includes(value))return "danger";if(["WAITING_BUSINESS","WAITING_CUSTOMER","WAITING_HUMAN","WAITING_INFORMATION","PENDING","SENDING"].includes(value))return "waiting";if(["CLOSED","CANCELLED","UNKNOWN"].includes(value))return "neutral";return "warning";}
function formatMoney(value){return value&&typeof value.amountCents==="number"?moneyFormatter.format(value.amountCents/100):"—";}
function formatDuration(value){if(value===null||value===undefined||!Number.isFinite(Number(value)))return "—";const ms=Number(value);if(ms<60000)return Math.round(ms/1000)+" s";const minutes=Math.floor(ms/60000);if(minutes<60)return minutes+" min";const hours=Math.floor(minutes/60);const rest=minutes%60;return rest?hours+" h "+rest+" min":hours+" h";}
function formatDate(value){if(!value)return "—";const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString("pt-BR");}
